"use client";
import {
  createContext,
  useContext,
  useSyncExternalStore,
  type HTMLAttributes,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
const Theme = createContext<"light" | "dark" | null>(null);
const subscribe = (notify: () => void) => {
  const observer = new MutationObserver(notify);
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ["class", "data-theme"],
  });
  return () => observer.disconnect();
};
export function useArtemisTheme(): "light" | "dark" {
  const explicit = useContext(Theme);
  const dark = useSyncExternalStore(
    subscribe,
    () =>
      document.documentElement.classList.contains("dark") ||
      document.documentElement.dataset.theme === "dark",
    () => true,
  );
  return explicit ?? (dark ? "dark" : "light");
}
/** Isolates this style's tokens and optional theme from surrounding interfaces. */
export function ArtemisScope({
  theme,
  children,
  className = "",
  style,
  ...props
}: HTMLAttributes<HTMLDivElement> & { theme?: "light" | "dark" }) {
  const inherited = useArtemisTheme(),
    mode = theme ?? inherited;
  return (
    <Theme.Provider value={mode}>
      <div {...props} style={{
          width: "100%",
          minWidth: 0,
          containerType: "inline-size",
          containerName: "artemis",
          ...style,
        }} className={`artemis ${className}`} data-artemis-theme={mode}>
        {children}
      </div>
    </Theme.Provider>
  );
}
function PortalContent({ children }: { children: ReactNode }) {
  const theme = useArtemisTheme();
  return (
    <div className="artemis" data-artemis-theme={theme} style={{ display: "contents" }}>
      {children}
    </div>
  );
}
export function artemisCreatePortal(
  children: ReactNode,
  target: Element | DocumentFragment,
  key?: string | null,
) {
  return createPortal(<PortalContent>{children}</PortalContent>, target, key);
}

"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_SWAP } from "../lib/ease";
import { artemisCx } from "../lib/utils";
export type ArtemisActionSwapAnimation = "blur" | "roll" | "cascade";
type SwapProps = {
    value: string;
    children: ReactNode;
    animation?: ArtemisActionSwapAnimation;
    className?: string;
};
function Swap({ value, children, animation = "blur", className, icon }: {
    icon: boolean;
} & SwapProps) {
    const reduce = useReducedMotion() === true, roll = animation === 'roll';
    const start = roll ? { opacity: 0, y: icon ? 12 : '90%', filter: 'blur(3px)' } : { opacity: 0, scale: icon ? .25 : .94, filter: 'blur(8px)' };
    const finish = { opacity: 1, y: 0, scale: 1, filter: 'blur(0px)' };
    const leave = roll ? { opacity: 0, y: icon ? -12 : '-90%', filter: 'blur(3px)' } : start;
    const timing = roll ? ARTEMIS_SPRING_SWAP : { duration: .2, ease: 'easeInOut' as const };
    return <span className={artemisCx(icon ? "art:relative art:inline-grid art:shrink-0 art:place-items-center art:overflow-hidden" : "art:relative art:-my-[0.08em] art:inline-block art:max-w-full art:whitespace-nowrap art:py-[0.08em] art:align-bottom", className)} style={icon ? undefined : { clipPath: 'inset(0 -999px)', WebkitClipPath: 'inset(0 -999px)' }}>
  {!icon && <span aria-hidden className="art:invisible art:inline-block art:whitespace-nowrap">{children}</span>}
  <AnimatePresence initial={false} mode={icon ? 'popLayout' : 'sync'}><motion.span key={`${animation}:${value}`} aria-hidden={icon || undefined} initial={reduce ? false : start} animate={{ ...finish, transition: reduce ? { duration: 0 } : timing }} exit={reduce ? undefined : { ...leave, transition: roll ? { duration: .14, ease: ARTEMIS_EASE_OUT } : timing }} className={icon ? "art:col-start-1 art:row-start-1 art:inline-flex art:items-center art:justify-center art:will-change-[opacity,filter,transform]" : "art:absolute art:left-0 art:top-[0.08em] art:inline-block art:max-w-full art:truncate art:will-change-[opacity,filter,transform]"}>{children}</motion.span></AnimatePresence>
 </span>;
}
function LetterSwap({ value, children, className }: SwapProps & { children: string }) {
    const letters = children.split("");
    return <span className={artemisCx("art:relative art:-my-[0.08em] art:inline-block art:max-w-full art:whitespace-nowrap art:py-[0.08em] art:align-bottom", className)} style={{ clipPath: "inset(0 -999px)", WebkitClipPath: "inset(0 -999px)" }}>
      <span aria-hidden className="art:invisible art:inline-block art:whitespace-nowrap">{letters.map((letter, position) => <span key={position} className="art:inline-block art:whitespace-pre">{letter}</span>)}</span>
      <span className="art:sr-only">{children}</span>
      <AnimatePresence initial={false}>
        <motion.span key={value} aria-hidden className="art:absolute art:left-0 art:top-[0.08em] art:inline-block art:whitespace-pre">
          {letters.map((letter, position) => <motion.span key={position} className="art:inline-block art:whitespace-pre art:will-change-[opacity,filter,transform]"
            initial={{ opacity: 0, y: "105%", filter: "blur(3px)" }}
            animate={{ opacity: 1, y: "0%", filter: "blur(0px)", transition: { ...ARTEMIS_SPRING_SWAP, delay: position * .025 } }}
            exit={{ opacity: 0, y: "-105%", filter: "blur(3px)", transition: { duration: .16, ease: ARTEMIS_EASE_OUT, delay: position * .0125 } }}>{letter}</motion.span>)}
        </motion.span>
      </AnimatePresence>
    </span>;
}
export function ArtemisActionSwapText(props: SwapProps) {
    const reduce = useReducedMotion();
    if (props.animation === "cascade" && typeof props.children === "string" && !reduce) return <LetterSwap {...props} children={props.children}/>;
    return <Swap {...props} animation={props.animation === "cascade" ? "roll" : props.animation} icon={false}/>;
}
export function ArtemisActionSwapIcon(props: SwapProps) { return <Swap {...props} icon/>; }

"use client";
// @zeus-internal
import { Dialog, DialogBackdrop, DialogPanel } from "../lib/headless";
import { AnimatePresence, MotionConfig, motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL } from "../lib/ease";
import { artemisCx } from "../lib/utils";
const PANEL_TRANSITION = { ...ARTEMIS_SPRING_PANEL, opacity: { duration: 0.55, ease: [0.22, 1, 0.36, 1] } } as const;
const BACKDROP_TRANSITION = { duration: 0.25, ease: ARTEMIS_EASE_OUT } as const;
const CLOSE_TRANSITION = { duration: 0.15, ease: ARTEMIS_EASE_OUT } as const;
export function ArtemisAnimatedModal({ open, onClose, children, panelClassName = "art:max-w-md art:rounded-3xl", containerClassName = "art:p-4", }: {
    open: boolean;
    onClose: () => void;
    children: ReactNode;
    panelClassName?: string;
    containerClassName?: string;
}) {
    const reduce = useReducedMotion();
    return (<AnimatePresence>
      {open ? (<Dialog static open={open} onClose={onClose} className="art:relative art:z-[100]">
          <MotionConfig transition={reduce ? { duration: 0 } : CLOSE_TRANSITION}>
            <DialogBackdrop as={motion.div} className="art:fixed art:inset-0 art:bg-foreground/10 art:backdrop-blur-xl" aria-hidden="true" initial={{ opacity: 0 }} animate={{ opacity: 1, transition: reduce ? { duration: 0 } : BACKDROP_TRANSITION }} exit={{ opacity: 0 }}/>
            <div className={artemisCx("art:fixed art:inset-0 art:z-[101] art:w-screen art:overflow-x-hidden art:overflow-y-auto", containerClassName)}>
              <div className="art:flex art:min-h-full art:items-center art:justify-center">
                <DialogPanel as={motion.div} className={artemisCx("art:max-h-[calc(100dvh-2rem)] art:w-full art:overflow-y-auto art:border art:border-border art:bg-background art:text-foreground art:will-change-transform", panelClassName)} initial={{ opacity: 0, y: 8, scale: 0.96 }} animate={{ opacity: 1, y: 0, scale: 1, transition: reduce ? { duration: 0 } : PANEL_TRANSITION }} exit={{ opacity: 0, y: 6, scale: 0.96 }}>
                  {children}
                </DialogPanel>
              </div>
            </div>
          </MotionConfig>
        </Dialog>) : null}
    </AnimatePresence>);
}

// @zeus-internal
import { artemisCx } from "../lib/utils";
const BASE = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50";
