const VARIANTS = {
    primary: "art:bg-primary art:text-primary-foreground art:hover:bg-primary/90",
    secondary: "art:border art:border-border art:bg-card art:text-foreground art:hover:border-border",
    outline: "art:border art:border-border art:bg-card art:hover:border-border",
    tertiary: "art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5",
    ghost: "art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground",
