// @zeus-internal
import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import { forwardRef } from "react";
import { type ArtemisButtonSize, type ArtemisButtonVariant, artemisButtonClasses } from "./button-classes";
import { ARTEMIS_SPRING_PRESS } from "../lib/ease";
export type ArtemisButtonProps = Omit<HTMLMotionProps<"button">, "className"> & {
  variant?: ArtemisButtonVariant; size?: ArtemisButtonSize; className?: string; rounded?: string;
};
export const ArtemisButton = forwardRef<HTMLButtonElement, ArtemisButtonProps>(function ArtemisButton({ variant, size, className, rounded, type = "button", tabIndex = 0, ...props }, ref) {
  const reduce = useReducedMotion();
  return <motion.button ref={ref} type={type} tabIndex={tabIndex} className={artemisButtonClasses({variant,size,className,rounded})} whileHover={reduce?undefined:{scale:1.01}} whileTap={reduce?undefined:{scale:.99}} transition={ARTEMIS_SPRING_PRESS} {...props}/>;
});
export type ArtemisButtonLinkProps = Omit<HTMLMotionProps<"a">, "className"> & {
