"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../lib/ease";
import { artemisCx } from "../lib/utils";
export type ArtemisDigitSwapDirection = "up" | "down";
export interface ArtemisDigitSwapProps {
    value: string | number;
    animationKey?: string | number;
    direction?: ArtemisDigitSwapDirection;
    duration?: number;
    stagger?: number;
    delay?: number;
    suffixLength?: number;
    className?: string;
    glyphClassName?: string;
    suffixClassName?: string;
}
type Travel = {
    sign: number;
    reduce: boolean;
};
function Glyph({ character, identity, travel, duration, wait, className }: {
    character: string;
    identity: string;
    travel: Travel;
    duration: number;
    wait: number;
    className?: string;
}) {
    const position = (edge: number, settings: Travel) => ({ opacity: edge === 0 ? 1 : 0, transform: `translateY(${settings.reduce ? 0 : edge * settings.sign * 45}%)` });
    return <span data-slot="digit-swap-glyph" className={artemisCx("art:relative art:inline-block art:h-[1.1em] art:shrink-0 art:leading-[1.1em] art:[clip-path:inset(0)]", /^[0-9]$/.test(character) && "art:w-[1ch] art:text-center")}>
  <span className="art:invisible">{character}</span>
  <AnimatePresence initial={false} custom={travel}>
   <motion.span key={identity} custom={travel} variants={{ arrive: (settings: Travel) => position(1, settings), settled: position(0, travel), leave: (settings: Travel) => position(-1, settings) }} initial="arrive" animate="settled" exit="leave" transition={{ duration: travel.reduce ? Math.min(duration, .12) : duration, delay: travel.reduce ? 0 : wait, ease: ARTEMIS_EASE_OUT }} className={artemisCx("art:absolute art:inset-0 art:flex art:items-center art:justify-center art:leading-none", className)}>{character}</motion.span>
  </AnimatePresence>
 </span>;
}
export function ArtemisDigitSwap({ value, animationKey, direction = "up", duration = .18, stagger = .006, delay = 0, suffixLength = 0, className, glyphClassName, suffixClassName }: ArtemisDigitSwapProps) {
    const reduce = useReducedMotion() === true, text = String(value), suffix = Math.max(0, text.length - Math.max(0, suffixLength));
    return <span data-slot="digit-swap" data-direction={direction} className={artemisCx("art:inline-flex art:items-baseline art:whitespace-nowrap", className)}>
  <span className="art:sr-only">{text}</span><span aria-hidden="true" className="art:inline-flex art:items-baseline">{Array.from(text).map((character, index) => character === ' ' ? <span key={index} className="art:inline-block art:w-[0.7ch]"/> : <Glyph key={index} character={character} identity={`${index}:${character}:${animationKey === undefined ? 'default' : 'key:' + animationKey}`} travel={{ sign: direction === 'up' ? 1 : -1, reduce }} duration={duration} wait={delay + index * stagger} className={artemisCx(glyphClassName, index >= suffix && suffixClassName)}/>)}</span>
 </span>;
}

"use client";
// @zeus-internal
import { animate, motion, type Transition, useMotionValue, useReducedMotion } from "motion/react";
import { createContext, type FocusEvent, type PointerEvent, type ReactNode, useCallback, useContext, useEffect, useId, useLayoutEffect, useMemo, useRef, useState, } from "react";
import { artemisCreatePortal as createPortal } from "../artemis-scope";
import { ARTEMIS_EASE_OUT } from "../lib/ease";
export type TooltipSide = "top" | "bottom";
const CLOSE_DELAY = 80;
const WARM_WINDOW = 230;
const GAP = 10;
const EDGE = 12;
const INSTANT: Transition = { duration: 0 };
const WRAPPER_TRANSITION: Transition = { duration: 0.15, ease: ARTEMIS_EASE_OUT };
const LABEL_TRANSITION: Transition = {
    opacity: { duration: 0.14, ease: ARTEMIS_EASE_OUT },
    y: { type: "spring", duration: 0.42, bounce: 0.18 },
};
const MORPH_SPRING: Transition = { type: "spring", stiffness: 215, damping: 25, mass: 1.2, restDelta: 0.001 };
const SIZE_SPRING: Transition = { type: "spring", stiffness: 158, damping: 18, mass: 1, restDelta: 0.001 };
type Size = {
    width: number;
    height: number;
};
type Rect = {
    left: number;
    top: number;
    width: number;
    height: number;
};
const ESTIMATED_SIZE: Size = { width: 90, height: 30 };
type Arrival = "fresh" | "jump" | "morph";
type Tip = {
    id: string;
    content: ReactNode;
    anchor: HTMLElement;
    rect: Rect;
    instant: boolean;
    arrival: Arrival;
    seq: number;
    labelKey: number;
    side: TooltipSide;
};
type TooltipApi = {
    enter: (id: string, content: ReactNode, el: HTMLElement, side: TooltipSide) => void;
    focus: (id: string, content: ReactNode, el: HTMLElement, side: TooltipSide) => void;
    hide: (id: string) => void;
};
const TooltipContext = createContext<TooltipApi | null>(null);
function rectOf(el: HTMLElement): Rect {
    const r = el.getBoundingClientRect();
    return { left: r.left, top: r.top, width: r.width, height: r.height };
}
export function ArtemisMorphicTooltipProvider({ children, delay = 90 }: {
    children: ReactNode;
    delay?: number;
}) {
    const reduce = useReducedMotion() === true;
    const [tip, setTip] = useState<Tip | null>(null);
    const [open, setOpen] = useState(false);
    const tipRef = useRef<Tip | null>(null);
    const openRef = useRef(false);
    const seqRef = useRef(0);
    const labelKeyRef = useRef(0);
    const warmUntil = useRef(0);
    const openTimer = useRef<{
        id: string;
        handle: number;
    } | null>(null);
    const closeTimer = useRef<number | null>(null);
    const commit = useCallback((next: Tip | null) => {
        tipRef.current = next;
        setTip(next);
    }, []);
    const cancelOpen = useCallback(() => {
        if (openTimer.current)
            window.clearTimeout(openTimer.current.handle);
        openTimer.current = null;
    }, []);
    const cancelClose = useCallback(() => {
        if (closeTimer.current !== null)
            window.clearTimeout(closeTimer.current);
        closeTimer.current = null;
    }, []);
    const api = useMemo<TooltipApi>(() => {
        const reveal = (id: string, content: ReactNode, el: HTMLElement, side: TooltipSide, instant: boolean) => {
            cancelOpen();
            cancelClose();
            const prev = tipRef.current;
            seqRef.current += 1;
            const sameTrigger = prev !== null && prev.id === id;
            if (!sameTrigger || instant)
                labelKeyRef.current += 1;
            commit({
                id,
                content,
                anchor: el,
                rect: rectOf(el),
                instant,
                arrival: prev ? "jump" : "fresh",
                seq: seqRef.current,
                labelKey: labelKeyRef.current,
                side,
            });
            openRef.current = true;
            setOpen(true);
        };
        return {
            enter(id, content, el, side) {
                const current = tipRef.current;
                if (openRef.current && current) {
                    cancelClose();
                    if (current.id === id)
                        return;
                    cancelOpen();
                    seqRef.current += 1;
                    commit({ ...current, id, content, anchor: el, rect: rectOf(el), instant: false, arrival: "morph", seq: seqRef.current, side });
                    return;
                }
                cancelOpen();
                if (current && performance.now() < warmUntil.current) {
                    reveal(id, content, el, side, false);
                    return;
                }
                openTimer.current = { id, handle: window.setTimeout(() => reveal(id, content, el, side, false), delay) };
            },
            focus(id, content, el, side) {
                const current = tipRef.current;
                if (openRef.current && current?.id === id) {
                    cancelClose();
                    return;
                }
                reveal(id, content, el, side, true);
            },
            hide(id) {
                if (openTimer.current?.id === id)
                    cancelOpen();
                if (!openRef.current || tipRef.current?.id !== id || closeTimer.current !== null)
                    return;
                closeTimer.current = window.setTimeout(() => {
                    closeTimer.current = null;
                    openRef.current = false;
                    warmUntil.current = performance.now() + WARM_WINDOW;
                    setOpen(false);
                    if (tipRef.current?.instant)
                        commit(null);
                }, CLOSE_DELAY);
            },
        };
    }, [cancelOpen, cancelClose, commit, delay]);
    useEffect(() => () => {
        cancelOpen();
        cancelClose();
    }, [cancelOpen, cancelClose]);
    const onExited = useCallback(() => {
        if (!openRef.current)
            commit(null);
    }, [commit]);
    return (<TooltipContext.Provider value={api}>
      {children}
      {tip ? createPortal(<TooltipLayer tip={tip} open={open} reduce={reduce} onExited={onExited}/>, document.body) : null}
    </TooltipContext.Provider>);
}
function TooltipLayer({ tip, open, reduce, onExited }: {
    tip: Tip;
    open: boolean;
    reduce: boolean;
    onExited: () => void;
}) {
    const labelRef = useRef<HTMLDivElement>(null);
    const boxRef = useRef<HTMLDivElement>(null);
    const x = useMotionValue(0);
    const y = useMotionValue(0);
    const width = useMotionValue(0);
    const height = useMotionValue(0);
    const [size, setSize] = useState<Size | null>(null);
    const [mountedFresh] = useState(() => tip.arrival === "fresh" && !tip.instant);
    useLayoutEffect(() => {
        const label = labelRef.current;
        if (!label)
            return;
        const measure = () => {
            const box = label.getBoundingClientRect();
            const next = { width: Math.ceil(box.width), height: Math.ceil(box.height) };
            setSize((prev) => (prev && prev.width === next.width && prev.height === next.height ? prev : next));
        };
        if (tip.arrival === "fresh" && !tip.instant) {
            const frame = window.requestAnimationFrame(measure);
            return () => window.cancelAnimationFrame(frame);
        }
        measure();
        return undefined;
    }, [tip.seq, tip.arrival, tip.instant]);
    const placeRef = useRef<(spring: boolean) => void>(() => { });
