// @zeus-internal
export type ArtemisSearchableCommand = { label: string; group?: string; keywords?: string[] };

// Search treats accents and punctuation as spelling variations. Camel-case labels
// expose their word boundaries, so searching for a later word works as expected.
function wordsOf(input: string): string[] {
  const separated = input.replace(/([a-z])(?=[A-Z])/g, '$1 ');
  return separated.normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase().match(/[\p{L}\p{N}]+/gu) ?? [];
}
function relevance(needle: string, words: string[]): number {
  let quality = 0;
  for (const word of words) {
    if (word === needle) return 100;
    if (word.startsWith(needle)) quality = Math.max(quality, 80);
    if (needle.length < 3 || word.length > needle.length + 2) continue;
    let cursor = 0;
    for (const letter of needle) {
      cursor = word.indexOf(letter, cursor);
      if (cursor < 0) break;
      cursor += 1;
    }
    if (cursor >= 0) quality = Math.max(quality, 20);
  }
  if (words.join(' ').includes(needle)) quality = Math.max(quality, 60);
  return quality;
}
export function artemisSearchCommands<T extends ArtemisSearchableCommand>(items: T[], query: string): T[] {
  const terms = wordsOf(query);
  if (terms.length === 0) return items;
  const phrase = terms.join(' ');
  const ranked: { item: T; score: number; order: number }[] = [];
  for (const [order, item] of items.entries()) {
    const fields = [wordsOf(item.label), wordsOf(item.group ?? ''), ...(item.keywords ?? []).map(wordsOf)];
    const label = fields[0].join(' ');
    let score = label === phrase ? 10000 : label.startsWith(phrase) ? 2000 : 0;
    let accepted = true;
    for (const term of terms) {
      let strongest = 0;
      for (let field = 0; field < fields.length; field += 1) {
        const match = relevance(term, fields[field]);
        if (match > 0) strongest = Math.max(strongest, match + (field === 0 ? 40 : 0));
      }
      if (strongest === 0) { accepted = false; break; }
      score += strongest;
    }
    if (accepted) ranked.push({ item, score, order });
  }
  ranked.sort((left, right) => right.score - left.score || left.order - right.order);
  return ranked.map(result => result.item);
}

